CREATE TABLE accounting_periods (id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,starts_on DATE NOT NULL,ends_on DATE NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),closed_by UUID REFERENCES users(id) ON DELETE SET NULL,closed_at TIMESTAMPTZ,UNIQUE(company_id,starts_on),CHECK(ends_on>=starts_on));
CREATE TABLE accounting_accounts (id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,code TEXT NOT NULL CHECK(length(code)<=32),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 180),account_type TEXT NOT NULL CHECK(account_type IN ('asset','liability','equity','income','expense')),normal_balance TEXT NOT NULL CHECK(normal_balance IN ('debit','credit')),is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,code));
CREATE TABLE accounting_journals (id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,period_id UUID REFERENCES accounting_periods(id) ON DELETE RESTRICT,number TEXT NOT NULL CHECK(length(number)<=60),entry_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','void')),reference TEXT NOT NULL DEFAULT '' CHECK(length(reference)<=120),description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=1000),source_type TEXT,source_id UUID,created_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,posted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,number));
CREATE TABLE accounting_journal_lines (id UUID PRIMARY KEY,journal_id UUID NOT NULL REFERENCES accounting_journals(id) ON DELETE CASCADE,account_id UUID NOT NULL REFERENCES accounting_accounts(id) ON DELETE RESTRICT,debit_cents BIGINT NOT NULL DEFAULT 0 CHECK(debit_cents>=0),credit_cents BIGINT NOT NULL DEFAULT 0 CHECK(credit_cents>=0),memo TEXT NOT NULL DEFAULT '' CHECK(length(memo)<=500),CHECK((debit_cents=0)<>(credit_cents=0)));
CREATE INDEX accounting_journals_company_date_idx ON accounting_journals(company_id,entry_date DESC);
CREATE INDEX accounting_journal_lines_account_idx ON accounting_journal_lines(account_id);
CREATE OR REPLACE FUNCTION accounting_posted_journal_balanced() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='posted' AND NOT EXISTS(SELECT 1 FROM accounting_journal_lines WHERE journal_id=NEW.id GROUP BY journal_id HAVING sum(debit_cents)=sum(credit_cents) AND sum(debit_cents)>0) THEN RAISE EXCEPTION 'posted journal must balance'; END IF; RETURN NEW; END $$;
CREATE TRIGGER accounting_journal_balance BEFORE INSERT OR UPDATE OF status ON accounting_journals FOR EACH ROW EXECUTE FUNCTION accounting_posted_journal_balanced();
